  "privWhat1": "Когда вы создаёте аккаунт, мы используем ваш адрес эл. почты, идентификатор аккаунта, данные аутентификации по паролю и статус подтверждения, чтобы предоставлять и защищать ваш аккаунт. Пароли обрабатываются поставщиком аутентификации в виде надёжных хешей; Cook не хранит пароли в читаемом виде. Мы сохраняем планировку кухни, выбранный язык, тему и единицы измерения, чтобы восстанавливать ваши настройки на всех устройствах. Для аккаунта нужны адрес эл. почты и пароль; рецепты можно смотреть и без аккаунта.",
  "privWhat2": "Обработка данных аккаунта и настроек необходима для предоставления запрошенной вами услуги аккаунта (подпункт (b) пункта 1 статьи 6 GDPR). Ограниченные записи для обеспечения безопасности и предотвращения злоупотреблений могут обрабатываться на основании законных интересов (подпункт (f) пункта 1 статьи 6) в необходимом объёме и после взвешивания интересов. Письма для подтверждения и сброса пароля — это служебные сообщения, а не маркетинг. Функция аккаунта не добавляет рекламу или аналитику.",
  "privStorage1": "Cook использует sessionStorage, чтобы переносить вашу кухню, ход приготовления и выбор между страницами в одной вкладке. Когда вы вошли в аккаунт, там также хранится ваш сеанс входа. Браузер обычно очищает эти данные по окончании сеанса вкладки, но восстановление сеансов браузера может их сохранить. Выход из аккаунта очищает данные Cook во вкладке. Закрытие уведомления о хранилище запоминается только в этой вкладке. Собственные скрипты Cook не устанавливают файлы cookie. Ваши хостинг-провайдеры или поставщики услуг могут выполнять собственную обработку в целях безопасности, которую нужно задокументировать до запуска.",
  "privStorage2": "Кнопки «ОК» и закрытия уведомления о хранилище только закрывают уведомление. Они не разрешают аналитику, рекламу или иное необязательное отслеживание. Любое будущее необязательное хранение потребует отдельного выбора до его начала, с таким же простым отказом и отзывом.",
  "privOther1": "Текущая голосовая функция списка рецептов запрашивает у country.is приблизительную страну по вашему IP-адресу, чтобы выбрать язык распознавания речи. Если вы используете распознавание через микрофон, браузер может отправлять звук своему поставщику распознавания речи. Ингредиенты можно также ввести вручную. Этих поставщиков, их политику и правовое основание этих функций необходимо проверить до публичного запуска.",
  "privProviders1": "Планируемый поставщик аккаунтов: Supabase (управляемый PostgreSQL и аутентификация) с выбранным регионом базы данных в ЕС. Поставщик эл. почты: [поставщик]. Хостинг сайта: [поставщик]. Оператор должен подтвердить фактических поставщиков, договоры об обработке, субобработчиков, места хранения журналов и любую передачу данных за пределы ЕЭЗ. Регион базы данных в ЕС сам по себе не исключает международную передачу. При необходимости укажите применимое решение о достаточности защиты или договорные гарантии и способ получить их копию.",
  "privRetention1": "Настройки аккаунта хранятся, пока ваш аккаунт активен. Вы можете запросить удаление через указанный выше контакт по вопросам конфиденциальности. До запуска оператор должен определить порядок ответа на запросы об удалении, срок истечения неподтверждённых аккаунтов и сроки хранения журналов безопасности и резервных копий. Удалённые данные могут оставаться в резервных копиях с ограниченным доступом до окончания задокументированного срока хранения.",
  "privRights1": "В зависимости от применимых условий вы можете запросить доступ, исправление, удаление, ограничение обработки или переносимость данных либо возразить против обработки на основании законного интереса. Свяжитесь с указанным выше оператором; на запросы обычно отвечают в течение месяца, а любое законное продление объясняется. Вы можете подать жалобу в надзорный орган, в том числе в венгерский NAIH на naih.hu. Cook не использует настройки аккаунта для автоматизированных решений, влекущих правовые или аналогично значимые последствия.",
